<map version="1.0.1"><node TEXT="AIGC视频创作课程菜单｜36门·54小时"><node TEXT="通用基础"><node TEXT="F01 AIGC视频入门：一条片子的生产地图（1h）"><node TEXT="建立从需求到交付的全流程认知，知道每一步应该产出什么。" /><node TEXT="成果：一张个人视频生产流程图" /><node TEXT="前置：—" /></node><node TEXT="F02 把需求讲清楚：从客户想法到创作任务书（1h）"><node TEXT="把“做得高级一点”等模糊要求转成可执行的创作约束。" /><node TEXT="成果：一页创作任务书与验收要点" /><node TEXT="前置：—" /></node><node TEXT="F03 选题与开头：让观众愿意继续看（1h）"><node TEXT="围绕用户问题、情绪和利益点，设计可测试的选题与前三秒开头。" /><node TEXT="成果：3个选题、3版开头与选择理由" /><node TEXT="前置：—" /></node><node TEXT="F04 脚本小课：把一个卖点写成30秒故事（1h）"><node TEXT="掌握可拍、可生成、可剪辑的短视频脚本写法。" /><node TEXT="成果：一份30秒脚本及压缩版" /><node TEXT="前置：—" /></node><node TEXT="F05 分镜小课：把文字变成镜头清单（1h）"><node TEXT="把脚本拆成可独立生成的短镜头，控制景别和连续性。" /><node TEXT="成果：一份4—6镜分镜表" /><node TEXT="前置：—" /></node><node TEXT="F06 提示词小课：从碰运气到可控修改（1h）"><node TEXT="用结构化描述明确主体、动作、环境、镜头和限制条件。" /><node TEXT="成果：一组提示词与修改对照记录" /><node TEXT="前置：—" /></node><node TEXT="F07 角色与产品一致性：建立可复用资产包（1h）"><node TEXT="建立角色、产品、场景与风格参照，减少跨镜头漂移。" /><node TEXT="成果：角色／产品卡及3张一致性候选图" /><node TEXT="前置：—" /></node><node TEXT="F08 关键帧设计：先定画面，再生成运动（1h）"><node TEXT="学习用起始画面、结束目标和动作衔接控制视频镜头。" /><node TEXT="成果：一组首尾画面与动作说明" /><node TEXT="前置：—" /></node><node TEXT="F09 视频生成诊断：镜头为什么失败（1h）"><node TEXT="识别动作畸变、穿帮和运动失控，选择成本较低的修复方案。" /><node TEXT="成果：一个镜头的修复前后对照" /><node TEXT="前置：—" /></node><node TEXT="F10 配音与声音：让画面有节奏和情绪（1h）"><node TEXT="为短片设计旁白、音乐与音效，保持听感清楚。" /><node TEXT="成果：一段20—30秒声音设计练习" /><node TEXT="前置：—" /></node><node TEXT="F11 剪辑与包装：把镜头组装成片（1h）"><node TEXT="用已有素材完成粗剪、字幕、封面与适配导出。" /><node TEXT="成果：一条15—30秒练习成片" /><node TEXT="前置：—" /></node><node TEXT="F12 成片审核：质量、授权与AI标识（1h）"><node TEXT="建立交付前的检查习惯，区分课堂样片与可公开发布作品。" /><node TEXT="成果：作品自查表与素材来源表" /><node TEXT="前置：—" /></node></node><node TEXT="工具入门"><node TEXT="T01 画布工具上手：做出第一条产品短片（2h）"><node TEXT="通过一个低复杂度产品案例，串联策划、图片、视频与成片。" /><node TEXT="成果：一条10—15秒、2—3镜产品练习片" /><node TEXT="前置：—" /></node><node TEXT="T02 转绘工具上手：拆解并重做一段视频（2h）"><node TEXT="用自摄或授权素材学习视频反推、风格改写和转绘输出。" /><node TEXT="成果：一段5—10秒转绘样片及拆解表" /><node TEXT="前置：—" /></node><node TEXT="T03 导演台上手：从短剧本到剧情样片（2h）"><node TEXT="围绕单场景短剧本体验剧本、分镜、资产和成片的完整流程。" /><node TEXT="成果：一条20—30秒、单场景剧情练习片" /><node TEXT="前置：—" /></node></node><node TEXT="案例实战"><node TEXT="P01 TVC广告：做一条15秒品牌概念片（2h）"><node TEXT="将一个品牌主张转成有视觉记忆点的商业广告样片。" /><node TEXT="成果：一条15秒TVC概念样片与创意说明" /><node TEXT="前置：T01" /></node><node TEXT="P02 电商产品视频：让商品卖点可视化（2h）"><node TEXT="从商品图片出发制作展示、使用场景和卖点字幕。" /><node TEXT="成果：一条15—20秒产品展示样片" /><node TEXT="前置：T01" /></node><node TEXT="P03 本地商家宣传：一条片讲清到店理由（2h）"><node TEXT="为咖啡店、民宿等真实场景设计可交付的轻宣传片。" /><node TEXT="成果：一条20—30秒商家宣传样片" /><node TEXT="前置：T01" /></node><node TEXT="P04 产品与服务讲解：把复杂流程讲明白（2h）"><node TEXT="把操作说明或服务流程转成易懂的视频讲解。" /><node TEXT="成果：一条30—45秒流程讲解样片" /><node TEXT="前置：T01" /></node><node TEXT="P05 数字人口播：做一条可信的讲解视频（2h）"><node TEXT="以授权形象和声音制作讲解型口播，处理口型、停顿和辅助画面。" /><node TEXT="成果：一条30—45秒数字人口播样片" /><node TEXT="前置：T01" /></node><node TEXT="P06 教育微课：把一个知识点讲懂（2h）"><node TEXT="面向开放大学和社会培训制作“一个问题、一种方法、一道练习”的教学短视频。" /><node TEXT="成果：一条45—60秒教学样片及1道自测题" /><node TEXT="前置：T01" /></node><node TEXT="P07 不出镜知识视频：用原创解释做内容（2h）"><node TEXT="用原创讲解和证据支撑的画面制作不出镜知识内容。" /><node TEXT="成果：一条30—45秒知识视频样片" /><node TEXT="前置：T01" /></node><node TEXT="P08 高传播创意短视频：反差、悬念与循环（2h）"><node TEXT="练习常见“爆款”叙事结构，把传播想法转成可测试的创意样片。" /><node TEXT="成果：一条10—20秒创意样片＋两版开头方案" /><node TEXT="前置：T01" /></node><node TEXT="P09 风格转绘：让同一段素材呈现新表达（2h）"><node TEXT="以自摄动作片段练习风格转换，关注人物、运动和时序稳定。" /><node TEXT="成果：一段转绘样片＋原片对照与风格说明" /><node TEXT="前置：T02" /></node><node TEXT="P10 视频出海本地化：从换语言到换表达（2h）"><node TEXT="把自有或授权样片改成适合一个目标市场的内容版本。" /><node TEXT="成果：一条15—30秒本地化样片＋双语脚本与改写表" /><node TEXT="前置：T02" /></node><node TEXT="P11 AI短剧：完成一个有反转的剧情场景（2h）"><node TEXT="围绕两人以内、一个场景的冲突完成短剧情制作。" /><node TEXT="成果：一条30—45秒短剧场景样片" /><node TEXT="前置：T03" /></node><node TEXT="P12 AI漫剧：把原创故事做成动态片段（2h）"><node TEXT="把原创或已获授权的短故事转成角色稳定、节奏清楚的动态漫片段。" /><node TEXT="成果：一条20—30秒漫剧样片＋后续两集梗概" /><node TEXT="前置：T03" /></node><node TEXT="P13 文旅与文化短片：让地方故事被看见（2h）"><node TEXT="围绕一项地方文化或一个景点制作叙事型宣传样片。" /><node TEXT="成果：一条20—30秒文旅文化样片" /><node TEXT="前置：T01/T03" /></node><node TEXT="P14 实拍＋AI特效：做一个可用的创意镜头（2h）"><node TEXT="在自摄镜头中加入生成元素，练习构图、遮挡与声音衔接。" /><node TEXT="成果：一段5—8秒特效镜头＋前后对照" /><node TEXT="前置：T01" /></node><node TEXT="P15 音乐视觉短片：把节奏变成画面（2h）"><node TEXT="为自有或授权音乐设计画面节奏与视觉主题。" /><node TEXT="成果：一条10—15秒音乐视觉片段" /><node TEXT="前置：T01" /></node></node><node TEXT="职业交付"><node TEXT="B01 接单与报价：把创作拆成可计价工作（1h）"><node TEXT="为视频服务限定范围，估算工时、生成成本和修改成本。" /><node TEXT="成果：一份模拟报价单与服务范围说明" /><node TEXT="前置：—" /></node><node TEXT="B02 修改与交付：让客户意见变成任务（1h）"><node TEXT="处理意见冲突、版本管理和项目归档，提高交付可追踪性。" /><node TEXT="成果：一份交付包目录＋修改确认单" /><node TEXT="前置：—" /></node><node TEXT="B03 作品集与获客：让客户看懂你能做什么（1h）"><node TEXT="针对一个细分客户群设计案例展示与服务介绍。" /><node TEXT="成果：一页作品集结构＋一项服务介绍" /><node TEXT="前置：—" /></node><node TEXT="B04 发布与复盘：用数据决定下一版怎么改（1h）"><node TEXT="用清楚的实验问题分析开头、完播和行动反馈。" /><node TEXT="成果：一份基于教学数据的A/B复盘表" /><node TEXT="前置：—" /></node><node TEXT="B05 系列化生产：把一条样片变成一组内容（1h）"><node TEXT="沉淀脚本、资产与审核模板，为周期性内容服务建立生产节奏。" /><node TEXT="成果：一份5期内容计划及生产模板" /><node TEXT="前置：—" /></node><node TEXT="B06 作品诊断与路演：完成一次模拟验收（1h）"><node TEXT="以已有样片为对象说明创意、制作过程、成本和改进路径。" /><node TEXT="成果：一份作品诊断表与改进计划" /><node TEXT="前置：—" /></node></node><node TEXT="路径与组课"><node TEXT="1天｜零基础产品视频体验"><node TEXT="第1天：F01 → T01 → P02 → F12（6h）" /></node><node TEXT="1天｜开放大学教师微课制作"><node TEXT="第1天：F01 → T01 → P06 → F12（6h）" /></node><node TEXT="2天｜商业广告与交付入门"><node TEXT="第1天：F01 → T01 → P02 → F12（6h）" /><node TEXT="第2天：F03 → F04 → P01 → B01 → B02（6h）" /></node><node TEXT="3天｜兼职视频服务起步"><node TEXT="第1天：F01 → T01 → P02 → F12（6h）" /><node TEXT="第2天：P05 → P03 → B03 → B04（6h）" /><node TEXT="第3天：F02 → F05 → P01 → B01 → B02（6h）" /></node><node TEXT="3天｜转绘与原创内容出海"><node TEXT="第1天：F01 → T02 → P09 → F12（6h）" /><node TEXT="第2天：T01 → P07 → F03 → F04（6h）" /><node TEXT="第3天：P10 → B01 → B02 → B04 → B06（6h）" /></node><node TEXT="3天｜导演台短剧与漫剧"><node TEXT="第1天：F01 → T03 → F07 → F05 → F12（6h）" /><node TEXT="第2天：F04 → F08 → P11 → P12（6h）" /><node TEXT="第3天：F09 → F10 → F11 → B01 → B02 → B06（6h）" /></node><node TEXT="5天｜一周综合创作营"><node TEXT="第1天：F01 → T01 → P02 → F12（6h）" /><node TEXT="第2天：F03 → F04 → F05 → F07 → P01（6h）" /><node TEXT="第3天：P05 → P06 → F10 → B05（6h）" /><node TEXT="第4天：T02 → P09 → P10（6h）" /><node TEXT="第5天：T03 → P11 → B01 → B06（6h）" /></node><node TEXT="7天｜作品集强化营"><node TEXT="第1天：F01 → T01 → P02 → F12（6h）" /><node TEXT="第2天：F03 → F04 → F05 → F07 → P01（6h）" /><node TEXT="第3天：P05 → P06 → F10 → B05（6h）" /><node TEXT="第4天：T02 → P09 → P10（6h）" /><node TEXT="第5天：T03 → P11 → B01 → B06（6h）" /><node TEXT="第6天：F08 → P12 → F09 → P14（6h）" /><node TEXT="第7天：B02 → B03 → B04 → P08 → F11（6h）" /></node></node></node></map>